// Works out, for every PMS booking, which emails are due TODAY (Malaysia time).
// Input: one item per booking from offlineBookings, with the lookups added before this step:
//   secret (booking private/main: door passcodes; guest details on imported bookings),
//   tenant (tenant private/main: name, email, phone), unit, property, ownerContact, bill (utility bill).
// Output: the same items with ready-to-use fields (guestName, checkInDisplay…) and one true/false flag per rule.

const MS_DAY = 24 * 60 * 60 * 1000;
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

// Today in Malaysia (UTC+8), as a whole day
const todayIso = new Date(Date.now() + 8 * 60 * 60 * 1000).toISOString().slice(0, 10);
const dayNum = (iso) => Math.round(Date.parse(iso + 'T00:00:00Z') / MS_DAY);
const today = dayNum(todayIso);

// "2026-08-17", "17/08/2026", a timestamp… → "2026-08-17" (or '' if it isn't a date)
function toIso(v) {
  if (!v) return '';
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  const t = Date.parse(s);
  return Number.isNaN(t) ? '' : new Date(t + 8 * 60 * 60 * 1000).toISOString().slice(0, 10);
}
function display(iso) {
  if (!iso) return '';
  const [y, mo, d] = iso.split('-').map(Number);
  return `${String(d).padStart(2, '0')} ${MONTHS[mo - 1]} ${y}`;
}
function addDays(iso, n) {
  return new Date(Date.parse(iso + 'T00:00:00Z') + n * MS_DAY).toISOString().slice(0, 10);
}
const money = (v) => (Number(v) || 0).toLocaleString('en-MY', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const text = (v) => (v === null || v === undefined ? '' : String(v).trim());
const isEmail = (s) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(text(s));
const norm = (v) => text(v).toLowerCase().replace(/\s+/g, '').replace(/-/g, '_');
// First non-empty value among several possible field names
function pick(objs, keys) {
  for (const o of objs) {
    if (!o || typeof o !== 'object') continue;
    for (const k of keys) if (text(o[k])) return text(o[k]);
  }
  return '';
}
function emailsFrom(v) {
  if (!v) return [];
  if (Array.isArray(v)) return v.flatMap(emailsFrom);
  if (typeof v === 'object') return emailsFrom(v.email || v.Email || '');
  return String(v).split(/[\s,;]+/).filter(isEmail);
}

// Long-term tenants: the next monthly due date (same day of the month as the check-in), today or later
function nextMonthly(arrivalIso, departureIso) {
  if (!arrivalIso) return '';
  const [ay, am, ad] = arrivalIso.split('-').map(Number);
  const [ty, tm] = todayIso.split('-').map(Number);
  for (let k = 0; k < 3; k++) {
    let y = ty, m = tm + k;
    while (m > 12) { m -= 12; y += 1; }
    const last = new Date(Date.UTC(y, m, 0)).getUTCDate();
    const iso = `${y}-${String(m).padStart(2, '0')}-${String(Math.min(ad, last)).padStart(2, '0')}`;
    if (iso > arrivalIso && iso >= todayIso && (!departureIso || iso < departureIso)) return iso;
  }
  return '';
}

return items.map((b) => {
  const secret = b.secret || {}, tenant = b.tenant || {}, unit = b.unit || {}, property = b.property || {};
  const unitInfo = unit.info || {}, propInfo = property.info || {}, bill = b.bill || null;

  // --- Who and where
  const guestName = pick([tenant, secret], ['name', 'fullName']) || 'Guest';
  const guestEmail = pick([tenant, secret], ['email']);
  const propertyName = text(b.propertyName) || text(property.name);
  const unitNumber = text(b.unitCode) || text(unit.unitCode);

  // --- Dates
  const checkIn = toIso(b.arrival), checkOut = toIso(b.departure);
  const daysUntilCheckIn = checkIn ? dayNum(checkIn) - today : 999999;
  const daysUntilCheckOut = checkOut ? dayNum(checkOut) - today : 999999;
  const isTenantActive = !!checkIn && !!checkOut && daysUntilCheckIn <= 0 && daysUntilCheckOut > 0;
  const stayingDays = checkIn && checkOut ? Math.abs(dayNum(checkOut) - dayNum(checkIn)) + 1 : 0;

  // --- Door passcodes (booking private part)
  const mainDoorPasscode = text(secret.mainDoorPasscode);
  const currentExpiry = toIso(secret.currentExpiryDate);
  const nextDoorPasscode = text(secret.nextDoorPasscode);
  const nextExpiry = toIso(secret.nextExpiryDate);
  const daysUntilPassExpiry = currentExpiry ? dayNum(currentExpiry) - today : 999999;

  // --- Rent
  const renewalDate = toIso(b.renewalDate) || (b.longTerm ? nextMonthly(checkIn, checkOut) : '');
  const daysUntilRenewal = renewalDate ? dayNum(renewalDate) - today : null;
  const rent = Number(b.monthlyRent) || Number(b.rental) || Number(b.amount) || 0;

  // --- Optional unit details (shown in emails only when filled in the PMS)
  const gmapLink = pick([b, unitInfo, propInfo, property], ['gmapLink', 'mapLink', 'googleMapsLink']);
  const wifiName = pick([secret, b, unitInfo], ['wifiName', 'wifiUsername', 'wifiSsid']);
  const wifiPassword = pick([secret, b, unitInfo], ['wifiPassword', 'wifiPasscode']);
  const mailboxPasscode = pick([secret, b, unitInfo], ['mailboxPasscode', 'mailboxCode']);
  const parkingLot = pick([b, unitInfo], ['parkingLot', 'parkingLotNumber', 'carParkNo', 'carParks']);
  const whatsappGroupLink = pick([b, unitInfo], ['whatsappGroupLink']);
  const line = (label, v) => (v ? `<strong>${label}:</strong> ${v}<br>` : '');
  const extrasHtml = line('Mailbox Passcode', mailboxPasscode) + line('WiFi Network', wifiName) + line('WiFi Password', wifiPassword) + line('Parking Lot', parkingLot);
  const locationHtml = line('Property Location', gmapLink);
  const whatsappHtml = whatsappGroupLink ? `<strong>WhatsApp group for any inquiries:</strong> ${whatsappGroupLink}<br>` : '';

  // --- Owner emails: the booking's own Owner Email (imported bookings) wins, else the unit owner's contact
  const fromBooking = emailsFrom(b.ownerEmail);
  const fromOwner = [...emailsFrom(b.ownerContact && b.ownerContact.email), ...emailsFrom(b.ownerContact && b.ownerContact.coOwners)];
  const ownerEmails = [...new Set(fromBooking.length ? fromBooking : fromOwner)].join(', ');

  // --- Statuses
  const rentalStatus = text(b.rentalStatus) || 'Paid';
  const passwordStatus = norm(b.passwordStatus);
  const moveInStatus = norm(b.moveInStatus), moveOutStatus = norm(b.moveOutStatus);
  const utilityStatus = bill ? norm(bill.utilityStatus) : '';
  const canEmailGuest = isEmail(guestEmail);

  const flags = {
    isPriorCheckIn: canEmailGuest && daysUntilCheckIn === 1,                                         // Rule 1
    isCheckInDay: canEmailGuest && daysUntilCheckIn === 0,                                           // Rule 2
    isExtensionReminder: canEmailGuest && daysUntilCheckOut === 7,                                    // Rule 3
    isPaymentReminder: canEmailGuest && daysUntilRenewal !== null && [7, 3, 1].includes(daysUntilRenewal)
      && rentalStatus === 'Unpaid' && isTenantActive && rent > 0,                                    // Rule 4
    // The next passcode being filled in is the "ready" signal (the PMS has no separate button for it).
    // Password Status "Hold" stops it for a booking.
    isTenantPassUpdate: canEmailGuest && daysUntilPassExpiry <= 1 && passwordStatus !== 'hold'
      && isTenantActive && !!nextDoorPasscode && !!nextExpiry,                                        // Rule 5
    isCheckoutReminder: canEmailGuest && daysUntilCheckOut === 0,                                     // Rule 6
    isThankYou: canEmailGuest && daysUntilCheckOut === -1,                                            // Rule 7
    isUtilityBill: canEmailGuest && utilityStatus === 'ready_to_send' && isTenantActive,             // Rule 8
    isOwnerMoveInNotify: moveInStatus === 'ready_to_send' && !!checkIn && daysUntilCheckIn <= 0 && !!ownerEmails,     // Rule 9
    isOwnerMoveOutNotify: moveOutStatus === 'ready_to_send' && !!checkOut && daysUntilCheckOut <= 0 && !!ownerEmails, // Rule 10
  };

  return {
    id: b.id,
    bookingNo: text(b.bookingNo),
    guestName, guestEmail, propertyName, unitNumber,
    checkIn, checkOut, checkInDisplay: display(checkIn), checkOutDisplay: display(checkOut),
    stayingDays, stayingDaysLabel: `${stayingDays} Days`,
    mainDoorPasscode, nextDoorPasscode,
    currentExpiryDisplay: display(currentExpiry),
    activeFromDisplay: currentExpiry ? display(addDays(currentExpiry, 1)) : '',
    nextExpiryDisplay: display(nextExpiry),
    renewalDisplay: display(renewalDate), rentalAmount: money(rent),
    extrasHtml, locationHtml, whatsappHtml,
    electricity: bill ? money(bill.electricity) : '', water: bill ? money(bill.water) : '', sewerage: bill ? money(bill.sewerage) : '',
    utilityTotal: bill ? money(bill.total || (Number(bill.electricity) || 0) + (Number(bill.water) || 0) + (Number(bill.sewerage) || 0)) : '',
    billPeriod: bill && (bill.periodFrom || bill.periodTo) ? `${display(toIso(bill.periodFrom))} – ${display(toIso(bill.periodTo))}` : '',
    invoiceLink: bill ? text(bill.invoiceLink) : '',
    ownerEmails,
    // Written to the PMS after the new-passcode email is sent (Rule 5)
    rotatePrivate: { mainDoorPasscode: nextDoorPasscode, currentExpiryDate: nextExpiry, nextDoorPasscode: '', nextExpiryDate: '' },
    ...flags,
    _check: { today: todayIso, daysUntilCheckIn, daysUntilCheckOut, daysUntilPassExpiry, daysUntilRenewal, isTenantActive, rentalStatus, passwordStatus, moveInStatus, moveOutStatus, utilityStatus, hasGuestEmail: canEmailGuest },
  };
});
